            if(mode!=1)foreach(var entry in Get(values,"destruction_operations",new Settings()).AsGodotDictionary()){var operation=entry.Value.AsGodotDictionary();if(Get(operation,"time",0).AsDouble()>controller.Call("_local",actor,time).AsDouble()+1e-8)continue;var copy=operation.Duplicate(true);var physical=_materials.resolve(values,Get(copy,"position",Vector3.Zero).AsVector3());if(Get(copy,"physical",false).AsBool()&&physical!=null){var material=physical.Get("values").AsGodotDictionary();double needed=Get(material,"hardness",12).AsDouble()+Get(material,"toughness",3).AsDouble(),fraction=Math.Clamp(Get(copy,"energy",20).AsDouble()/Math.Max(.01,needed),0,1);if(fraction<.05)continue;copy["amount"]=copy["amount"].AsDouble()*fraction;copy["radius"]=copy["radius"].AsDouble()*Math.Sqrt(fraction);}operations[entry.Key]=copy;}
