peration,"direction",Vector3.Right).AsVector3()).Normalized(),(float)Math.Clamp(Get(operation,"direction_bias",0).AsDouble(),0,1));}fragments.Add(new Settings{["id"]=id+":fragment:"+row["id"].AsString(),["mesh"]=row["mesh"],["pose"]=fragmentPose,["v"]=state["v"].AsVector3()+state["w"].AsVector3().Cross(offset)+direction*(float)impulse,["w"]=state["w"],["mass"]=Math.Max(.0001,config["mass"].AsDouble()*row["volume"].AsDouble()/Math.Max(.00001,total)),["sleep"]=0.0,["structure_origin"]=row["center"]});}state["destruction_fragments"]=fragments;controller.EmitSignal("mesh_fractured",id,time,fragments.Count);controller.Get("debris").AsGodotObject().Call("emit",controller,id,id,"fracture",time,eventPoint,eventNormal,state["v"],eventEnergy>0?eventEnergy:20);}
